import{_ as a,o as t,c as o,ae as n}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"Base64-encoded configuration values","description":"","frontmatter":{"id":"4689777057","title":"Base64-encoded configuration values","state":"Approved","created":"2026-10-25T00:00:00.000Z","tags":["secret","encoding","configuration","environment-variables"],"category":"Platform"},"headers":[],"relativePath":"adrs/4689777057/README.md","filePath":"adrs/4689777057/README.md"}'),s={name:"adrs/4689777057/README.md"};function i(r,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="base64-encoded-configuration-values" tabindex="-1">Base64-encoded configuration values <a class="header-anchor" href="#base64-encoded-configuration-values" aria-label="Permalink to &quot;Base64-encoded configuration values&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Configuration values travel through carriers that only hold a single line of text: environment variables, <code>.env</code> files, CI variable stores, container orchestrator manifests and secret managers. Some values do not fit. TLS certificates and CA bundles are multi-line PEM, and a Google service account key is a multi-line JSON document with an embedded PEM key. Each carrier mangles newlines, quotes and backslashes differently, so the same value pasted into two carriers can reach the program in two different shapes. This happens to public values and secrets alike.</p><p>Encoding the value as base64 makes it a single line of safe characters, but the program reading it has to know it was encoded. Putting that knowledge in the reader&#39;s configuration, such as an <code>encoding</code> field next to the variable name, does not travel: the operator who stores the value often cannot change the reader&#39;s configuration, and a value shared by programs in different languages would need the same field in every one of them. The value has to describe itself.</p><p>Other ecosystems already do this, such as the <code>base64:</code> prefix Laravel uses for <code>APP_KEY</code>.</p><p><a href="./../3610135900/README.html">ADR#3610135900</a> defines a syntax that marks a value as a secret so scanners can find it. This ADR does not replace it; it defines how a value is carried, not what it is.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><h3 id="when-to-encode" tabindex="-1">When to encode <a class="header-anchor" href="#when-to-encode" aria-label="Permalink to &quot;When to encode&quot;">​</a></h3><p>Encoding is a last resort for a value its carrier cannot hold unchanged. It costs readability: people, diffs and scanners can no longer see what the value is.</p><ul><li>You <strong>SHOULD NOT</strong> encode a value that already fits on one line of printable ASCII, such as a URL, an API token or a <code>whsec_</code> signing secret.</li><li>You <strong>SHOULD NOT</strong> encode a value when the carrier already preserves it, such as a Kubernetes ConfigMap or Secret, which delivers the exact bytes to the program, or a secret manager that returns them unchanged. A Secret&#39;s <code>data</code> field is already base64, so encoding the value again only adds a layer.</li><li>You <strong>MAY</strong> encode a value only when its carrier cannot hold it unchanged, such as a multi-line PEM certificate in a <code>.env</code> file or a CI store that strips newlines.</li></ul><h3 id="writing-a-value" tabindex="-1">Writing a value <a class="header-anchor" href="#writing-a-value" aria-label="Permalink to &quot;Writing a value&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> write an encoded value as <code>base64:</code> followed by the standard base64 encoding of the value&#39;s bytes, as defined in <a href="https://datatracker.ietf.org/doc/html/rfc4648#section-4" target="_blank" rel="noreferrer">RFC 4648 section 4</a>, with padding:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base64:LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0tCk1JSUIKLS0tLS1FTkQgQ0VSVElGSUNBVEUtLS0tLQo=</span></span></code></pre></div></li><li><p>You <strong>MUST</strong> encode a text value as its UTF-8 bytes.</p></li><li><p>You <strong>MUST NOT</strong> change the bytes before encoding, such as by normalizing newlines or trimming whitespace, so the decoded value is the original one.</p></li><li><p>You <strong>MUST</strong> write the prefix in lowercase.</p></li><li><p>You <strong>SHOULD</strong> write the encoded part as a single line, such as the output of <code>base64 -w0</code> or of <code>base64</code> on macOS.</p></li><li><p>You <strong>MUST</strong> encode a value that itself begins with <code>base64:</code>, so it is not mistaken for an encoded one.</p></li><li><p>You <strong>MUST NOT</strong> use the URL-safe alphabet or drop the padding.</p></li></ul><h3 id="reading-a-value" tabindex="-1">Reading a value <a class="header-anchor" href="#reading-a-value" aria-label="Permalink to &quot;Reading a value&quot;">​</a></h3><ul><li>You <strong>MUST</strong> decode a value that begins with <code>base64:</code> and use the decoded value in its place.</li><li>You <strong>MUST</strong> use a value that does not begin with <code>base64:</code> as is. You <strong>MUST NOT</strong> guess an encoding from the content of a value.</li><li>You <strong>MUST</strong> decode exactly once. A decoded value that begins with <code>base64:</code> is the value itself, not another layer to decode.</li><li>You <strong>MUST</strong> ignore ASCII whitespace inside the encoded part, so wrapped output of <code>base64</code> is accepted. Base64 contains no whitespace, so this cannot change the result.</li><li>You <strong>MUST</strong> fail when the encoded part is not valid standard base64. When the reader needs text, it <strong>MUST</strong> also fail when the decoded bytes are not valid UTF-8.</li><li>You <strong>SHOULD</strong> decode when the configuration is loaded and fail at startup, not each time the value is used.</li></ul><h3 id="encoding-a-secret" tabindex="-1">Encoding a secret <a class="header-anchor" href="#encoding-a-secret" aria-label="Permalink to &quot;Encoding a secret&quot;">​</a></h3><p>The <a href="./../3610135900/README.html">ADR#3610135900</a> marker is what tells scanners, logs and people that a value is sensitive. Encoding hides the content, so the marker has to stay readable.</p><ul><li><p>You <strong>MUST</strong> mark every encoded secret with the <a href="./../3610135900/README.html">ADR#3610135900</a> syntax, so scanners detect it without decoding it.</p></li><li><p>You <strong>MUST</strong> keep the marker outside the encoding: put <code>base64:</code> at the start of the secret value part, after the namespace identifiers.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>secret:tls:private-key:base64:LS0tLS1CRUdJTiBQUklWQVRFIEtFWS0tLS0tCk1JSUUKLS0tLS1FTkQgUFJJVkFURSBLRVktLS0tLQo=</span></span></code></pre></div></li><li><p>You <strong>MUST NOT</strong> encode a marked value as a whole, such as <code>base64:c2VjcmV0Oi4uLg==</code>, since that hides the marker.</p></li><li><p>When reading, you <strong>MUST</strong> parse the <a href="./../3610135900/README.html">ADR#3610135900</a> syntax first, then apply <a href="#reading-a-value">Reading a value</a> to its secret value part.</p></li><li><p>You <strong>MUST NOT</strong> include a secret, encoded or decoded, in an error or a log. Name where the value came from instead, such as the variable or field.</p></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://datatracker.ietf.org/doc/html/rfc4648" target="_blank" rel="noreferrer">RFC 4648: The Base16, Base32, and Base64 Data Encodings</a></li><li><a href="https://laravel.com/docs/encryption#configuration" target="_blank" rel="noreferrer">Laravel encryption configuration</a></li></ul>',19)])])}const p=a(s,[["render",i]]);export{g as __pageData,p as default};
